const nums=s=>String(s||'').replace(/https?:\/\/[^\s)\]>]+/g,' ').match(/\b\d+(?:[.,]\d+)?\b/g)||[];
const words=s=>String(s||'').trim().split(/\s+/).filter(Boolean).length;
const out=[];
for(const base of rows){
 const c=candidates.get(String(base.queue_id)); let subject=String(c?.subject||'').trim(); let body=String(c?.body||'').trim(); let valid=!!subject&&!!body;
 const baseUrls=urls(base.SendBody); const outUrls=urls(body);
 if(valid && (outUrls.some(u=>!baseUrls.includes(u)) || baseUrls.some(u=>!outUrls.includes(u)))) valid=false;
 const allowedNums=new Set([...nums(base.SendSubject),...nums(base.SendBody),...nums(base.target_name)]);
 if(valid && nums(subject+' '+body).some(n=>!allowedNums.has(n))) valid=false;
 const wc=words(body), follow=String(base.phase)==='follow_up'; if(valid && (wc<(follow?20:45)||wc>(follow?120:210))) valid=false;
